package io.github.long0823.tclbondriver;
import android.content.Context;import org.json.*;import java.io.*;import java.util.*;
/** User-approved, application-only TCL foreground and boot exceptions. */
final class TclPolicy {
 private static final String URI="content://com.tcl.config.ConfigProvider/AppBootPolicy",PACKAGE="io.github.long0823.tclbondriver";
 private static String quote(String s){return "'"+s.replace("'","'\\''")+"'";}
 static synchronized void configure(Context c,boolean enable)throws Exception{String raw=PhonePairing.capture("content query --uri "+URI+" --projection config_content");int offset=raw.indexOf("config_content=");if(offset<0)throw new IOException("TCLの常駐許可設定を読めません");JSONArray config=new JSONArray(raw.substring(offset+15).trim());JSONObject policy=config.getJSONObject(0);android.content.SharedPreferences prefs=c.getSharedPreferences(NetworkService.PREFS,0);Set<String> added=new HashSet<>(prefs.getStringSet("tcl_added_lists",Collections.emptySet()));boolean changed=false;for(String field:new String[]{"serviceStartForegroundWhiteList","autoStartWhiteList","serviceWhiteList","restartServiceWhiteList","broadcastWhiteList"}){JSONObject list=policy.optJSONObject(field);if(list==null)continue;JSONArray names=list.optJSONArray("packageName");if(names==null)continue;boolean exists=false;for(int i=0;i<names.length();i++)if(PACKAGE.equals(names.optString(i)))exists=true;if(enable&&!exists){names.put(PACKAGE);added.add(field);changed=true;}else if(!enable&&added.contains(field)){JSONArray replacement=new JSONArray();for(int i=0;i<names.length();i++)if(!PACKAGE.equals(names.optString(i)))replacement.put(names.get(i));list.put("packageName",replacement);changed=true;}}if(changed){File file=new File(c.getCacheDir(),"tcl-policy-update.json");try(java.io.OutputStream out=new java.io.FileOutputStream(file)){out.write(config.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}String result;try{result=PhonePairing.capture("CLASSPATH="+quote(c.getApplicationInfo().sourceDir)+" app_process /system/bin io.github.long0823.tclbondriver.RootConfigMain "+quote(file.getAbsolutePath()));}finally{file.delete();}if(!result.contains("Updated 1 rows"))throw new IOException("TCLの常駐許可を保存できません");}prefs.edit().putStringSet("tcl_added_lists",enable?added:Collections.emptySet()).commit();String current=PhonePairing.capture("settings get global stay_on_while_plugged_in").trim();if(enable){if(!prefs.contains("original_stay_on"))prefs.edit().putString("original_stay_on",current).commit();PhonePairing.capture("settings put global stay_on_while_plugged_in 1");}else if(prefs.contains("original_stay_on")){if(current.equals("1")){String original=prefs.getString("original_stay_on","0");if(!original.matches("null|[0-9]+"))throw new IOException("電源設定の復元値が不正です");PhonePairing.capture(original.equals("null")?"settings delete global stay_on_while_plugged_in":"settings put global stay_on_while_plugged_in "+original);}prefs.edit().remove("original_stay_on").commit();}}
}